include "globals.mzn";

% Number of cows
int: num_cows = 25;

% Number of sons
int: num_sons = 5;

% Number of cows each son should have
array[1..num_sons] of int: cow_distribution = [7, 6, 5, 4, 3];

% Milk production of each cow
array[1..num_cows] of int: milk_production = [i | i in 1..num_cows];

% Assignment of cows to sons
array[1..num_cows] of var 0..num_sons-1: cow_assignments;

% Each son should have the correct number of cows
constraint forall(i in 1..num_sons) (
    sum(j in 1..num_cows) (cow_assignments[j] == i-1) == cow_distribution[i]
);

% The total quantity of milk produced should be the same for each son
constraint forall(i, j in 1..num_sons where i < j) (
    sum(k in 1..num_cows) (cow_assignments[k] == i-1) * milk_production[k] ==
    sum(k in 1..num_cows) (cow_assignments[k] == j-1) * milk_production[k]
);

% Solve the problem
solve satisfy;

% Print the assignment of cows to sons
output [
    "cow_assignments: [",
    join(", ", [show(cow_assignments[i]) | i in 1..num_cows]),
    "]"
];
```

