```minizinc
include "globals.mzn";

int: n = 8; % number of rows
int: m = 8; % number of columns
array[1..n, 1..m] of int: game_data = [
    [2, 3, -1, 2, 2, -1, 2, 1],
    [-1, -1, 4, -1, -1, 4, -1, 2],
    [-1, -1, -1, -1, -1, -1, 4, -1],
    [-1, 5, -1, 6, -1, -1, -1, 2],
    [2, -1, -1, -1, 5, 5, -1, 2],
    [1, 3, 4, -1, -1, -1, 4, -1],
    [0, 1, -1, 4, -1, -1, -1, 3],
    [0, 1, 2, -1, 2, 3, -1, 2]
];

array[1..n, 1..m] of var bool: mines;

% count the number of mines around each cell
constraint forall(i in 1..n, j in 1..m) (
    game_data[i, j] >= 0 -> 
    sum([mines[i2, j2] | i2 in max(1, i-1)..min(n, i+1), j2 in max(1, j-1)..min(m, j+1), (i2, j2) != (i, j)]) = game_data[i, j]
);

% all -1 cells are either mines or not
constraint forall(i in 1..n, j in 1..m) (
    game_data[i, j] = -1 -> mines[i, j] \/ not mines[i, j]
);

% solve
solve satisfy;

% print result
output [
    "{",
    join(",", [
        "\"" ++ "mines" ++ "\": ["
        ++ join(",", [
            "[" ++ join(",", [if mines[i, j] then "1" else "0" | j in 1..m]) ++ "]"
            | i in 1..n
        ])
        ++ "]"
    ]),
    "}"
];
```

