constraint forall(r in 1..max_rooms) (
    forall(i, j in 1..num_requests where i < j and room_assignments[i] = r and room_assignments[j] = r) (
        (start_data[i] >= end_data[j]) or (start_data[j] >= end_data[i])
    )
);

% Solve
solve satisfy;

% Print the room assignments for the requests
output [
    "{",
    "\"room_assignments\": [",
    join(", ", [show(room_assignments[i]) | i in 1..num_requests]),
    "]",
