include "globals.mzn";

% Input data
int: rows = 8;
int: row_rule_len = 2;
array[1..rows, 1..row_rule_len] of int: row_rules = [
    [0, 1],
    [0, 2],
    [4, 4],
    [0, 12],
    [0, 8],
    [0, 9],
    [3, 4],
    [2, 2]
];
int: cols = 13;
int: col_rule_len = 2;
array[1..cols, 1..col_rule_len] of int: col_rules = [
    [0, 2],
    [2, 1],
    [3, 2],
    [0, 6],
    [1, 4],
    [0, 3],
    [0, 4],
    [0, 4],
    [0, 4],
    [0, 5],
    [0, 4],
    [1, 3],
    [0, 2]
];

% Variables
array[1..rows, 1..cols] of var bool: board;

% Constraints
constraint forall(i in 1..rows) (
    let {
        array[1..row_rule_len] of int: rule = row_rules[i];
        array[1..cols] of var int: row = [if board[i, j] then 1 else 0 | j in 1..cols];
        array[1..row_rule_len] of var int: blocks = [sum([row[k] | k in j..(j + rule[j] - 1)]) | j in 1..row_rule_len where j + rule[j] - 1 <= cols];
    } in
    forall(j in 1..row_rule_len) (
        blocks[j] = rule[j]
    )
);

constraint forall(j in 1..cols) (
    let {
        array[1..col_rule_len] of int: rule = col_rules[j];
        array[1..rows] of var int: col = [if board[i, j] then 1 else 0 | i in 1..rows];
        array[1..col_rule_len] of var int: blocks = [sum([col[k] | k in i..(i + rule[i] - 1)]) | i in 1..col_rule_len where i + rule[i] - 1 <= rows];
    } in
    forall(i in 1..col_rule_len) (
        blocks[i] = rule[i]
    )
);

% Output
output [
    "{\n",
    "  \"board\": [\n",
    join(",\n", [
        "    [" ++ join(", ", [if board[i, j] then "1" else "0" | j in 1..cols]) ++ "]"
        | i in 1..rows
    ]),
    "\n  ]\n",
    "}"
];
```

This model uses a 2D array `board` to represent the Nonogram grid, where `board[i, j]` is `true` if the cell at row `i` and column `j` is shaded, and `false` otherwise. The constraints are defined using the `forall` keyword, which applies a constraint to each row and column. The `let` keyword is used to define local variables and constraints.

The first constraint checks that each row satisfies its corresponding rule. It does this by creating an array `row` of 1s and 0s representing the shaded cells in the row, and then creating an array `blocks` of the lengths of the shaded blocks in the row. The constraint then checks that each block in `blocks` has the same length as the corresponding block in the rule.

The second constraint checks that each column satisfies its corresponding rule, in a similar way to the first constraint.

Finally, the output is defined using the `output` keyword, which prints the solution board as a JSON object.

