```minizinc
include "globals.mzn";

% Number of teams
int: n_teams = 8;

% Number of weeks
int: n_weeks = n_teams - 1;

% Number of periods per week
int: n_periods = n_teams / 2;

% Team indices
set of int: Teams = 0..n_teams-1;

% Week indices
set of int: Weeks = 1..n_weeks;

% Period indices
set of int: Periods = 1..n_periods;

% Home and away schedules
array[Weeks, Periods, Teams] of var bool: home_schedule;
array[Weeks, Periods, Teams] of var bool: away_schedule;

% Each team plays once a week
constraint forall(w in Weeks) (
    forall(t in Teams) (
        sum(p in Periods) (home_schedule[w, p, t] + away_schedule[w, p, t]) = 1
    )
);

% Each team plays at most twice in the same period over the tournament
constraint forall(p in Periods, t in Teams) (
    sum(w in Weeks) (home_schedule[w, p, t] + away_schedule[w, p, t]) <= 2
);

% Each team plays every other team
constraint forall(t1 in Teams, t2 in Teams where t1 < t2) (
    sum(w in Weeks, p in Periods) (home_schedule[w, p, t1] /\
                                   away_schedule[w, p, t2]) = 1 /\
    sum(w in Weeks, p in Periods) (home_schedule[w, p, t2] /\
                                   away_schedule[w, p, t1]) = 1
);

% Each period has exactly two teams
constraint forall(w in Weeks, p in Periods) (
    sum(t in Teams) (home_schedule[w, p, t]) = 1 /\
    sum(t in Teams) (away_schedule[w, p, t]) = 1
);

% Each team plays at home and away against each other team
constraint forall(t1 in Teams, t2 in Teams where t1 < t2) (
    exists(w in Weeks, p in Periods) (
        home_schedule[w, p, t1] /\ away_schedule[w, p, t2]
    ) /\
    exists(w in Weeks, p in Periods) (
        home_schedule[w, p, t2] /\ away_schedule[w, p, t1]
    )
);

% Solve the model
solve satisfy;

% Print the home and away schedules
output [
    "{",
    "\"home\": [",
    join(",\n", [
        "[" ++ join(", ", [
            if home_schedule[w, p, t] then "1" else "0" | t in Teams
        ]) ++ "]" | w in Weeks, p in Periods
    ]),
    "],\n",
    "\"away\": [",
    join(",\n", [
        "[" ++ join(", ", [
            if away_schedule[w, p, t] then "1" else "0" | t in Teams
        ]) ++ "]" | w in Weeks, p in Periods
    ]),
    "]",
    "}"
];
```

