include "globals.mzn";

% Number of vertices
int: N = 10;

% Degrees of vertices
array[1..N] of var int: d;

% Adjacency matrix
array[1..N, 1..N] of var bool: adj;

% Objective: find a valid degree sequence and adjacency matrix
constraint forall(i in 1..N-1) (d[i] >= d[i+1]);
constraint forall(i in 1..N) (d[i] > 0);
constraint forall(i in 1..N) (d[i] mod 3 = 0);
constraint sum(d) mod 12 = 0;

% Constraints for the adjacency matrix
constraint forall(i in 1..N, j in 1..N) (adj[i, j] -> i < j);
constraint forall(i in 1..N) (sum(j in 1..N) (adj[i, j]) = d[i]);
constraint forall(i in 1..N, j in 1..N) (adj[i, j] <-> adj[j, i]);

% Diamond-free constraint
constraint forall(a in 1..N, b in a+1..N, c in b+1..N, d in c+1..N) (
    adj[a, b] + adj[a, c] + adj[a, d] + adj[b, c] + adj[b, d] + adj[c, d] <= 4
);

% Solve
solve satisfy;

% Output
output [
    "matrix: \n",
    join("\n", [
        join(" ", [if adj[i, j] then "1" else "0" | j in 1..N]) | i in 1..N
    ])
];
```

