    exists(p in 1..num_bales, q in p+1..num_bales) (bales[p] + bales[q] = weights[i])
);

% Symmetry breaking: order the bales by weight
constraint forall(i in 1..num_bales-1) (bales[i] <= bales[i+1]);

% Solve the problem
solve satisfy;

% Print the weights of each bale
output [
