constraint forall(i in index(nums)) (not selected[i] -> nums[i] >= -10000);
constraint sum([if selected[i] then 1 else 0 | i in index(nums)]) = 3;

% Find three elements that sum to zero
constraint exists(a in index(nums)) (exists(b in index(nums)) (exists(c in index(nums)) 
    (a < b /\ b < c /\ selected[a] /\ selected[b] /\ selected[c] /\ nums[a] + nums[b] + nums[c] = 0)));

% Solve
solve satisfy;

% Output
output [
    "{",
    "\"selected\": [",
    join(", ", [if selected[i] then show(i+1) else "null" | i in index(nums)]),
    "]",
    "}"
];
